body:
`chatSpanAttrsForUsage` always POSTs to `chat/completions`, which `classifyOperation`
routes to `parseChatResponse`. `parseCompletionResponse` (middleware.go:351) has its
own, separately-gated cache_read.input_tokens check at middleware.go:394, but it has
no test coverage of its own — a regression specific to that branch would not be caught.
This mirrors the streaming-side gap already flagged on `processCompletionChunk`.

```suggestion
}

// completionSpanAttrsForUsage runs one non-streaming legacy completion call
// through the middleware with the given usage JSON and returns the recorded
// span attributes.
func completionSpanAttrsForUsage(t *testing.T, usage string) []attribute.KeyValue {
	t.Helper()
	sr := setupTestTracer(t)

	req, _ := http.NewRequest(
		http.MethodPost,
		"http://api.openai.com/v1/completions",
		io.NopCloser(bytes.NewReader([]byte(`{"model":"gpt-3.5-turbo-instruct"}`))),
	)
	respBody := `{"id":"cmpl-1","model":"gpt-3.5-turbo-instruct","choices":[{"finish_reason":"stop"}],"usage":` + usage + `}`
	next := func(_ *http.Request) (*http.Response, error) {
		return &http.Response{
			StatusCode: http.StatusOK,
			Header:     http.Header{"Content-Type": []string{"application/json"}},
			Body:       io.NopCloser(bytes.NewReader([]byte(respBody))),
		}, nil
	}

	_, err := OtelMiddleware()(req, next)
	require.NoError(t, err)

	spans := sr.Ended()
	require.Len(t, spans, 1)
	return spans[0].Attributes()
}

// TestCompletionRecordsCacheReadTokens verifies the legacy completions
// endpoint records cache_read.input_tokens the same way the chat endpoint
// does, and that it is not folded into gen_ai.usage.input_tokens.
func TestCompletionRecordsCacheReadTokens(t *testing.T) {
	attrs := completionSpanAttrsForUsage(t,
		`{"prompt_tokens":2048,"completion_tokens":64,"total_tokens":2112,`+
			`"prompt_tokens_details":{"cached_tokens":1024}}`)

	assertInt64Attribute(t, attrs, cacheReadTokensKey, 1024)
	assertInt64Attribute(t, attrs, "gen_ai.usage.input_tokens", 2048)
	assertInt64Attribute(t, attrs, "gen_ai.usage.total_tokens", 2112)
}

// TestCompletionOmitsCacheReadTokensWhenUnused verifies the attribute is
// absent rather than recorded as zero when the request did not hit the cache.
func TestCompletionOmitsCacheReadTokensWhenUnused(t *testing.T) {
	attrs := completionSpanAttrsForUsage(t,
		`{"prompt_tokens":10,"completion_tokens":20,"total_tokens":30,`+
			`"prompt_tokens_details":{"cached_tokens":0}}`)

	assertNoAttribute(t, attrs, cacheReadTokensKey)
	assertInt64Attribute(t, attrs, "gen_ai.usage.input_tokens", 10)
}
