body:
`UnquoteGoflagsToken` has no direct test. `TestForceModMod` and
`TestStripToolexecFromGoflags` cover the helper only through its consumers.
No test pins the contract directly: a mismatched pair (`'x"`) returns the
token unchanged, a one-character token returns unchanged, and a double
layer (`"'x'"`) strips one layer only.

A table test in `tool/util/go_test.go` would protect that contract:

```go
func TestUnquoteGoflagsToken(t *testing.T) {
	tests := []struct {
		name  string
		token string
		want  string
	}{
		{"unquoted token unchanged", "-mod=mod", "-mod=mod"},
		{"single-quoted token stripped", "'-mod=readonly'", "-mod=readonly"},
		{"double-quoted token stripped", `"-mod=readonly"`, "-mod=readonly"},
		{"mismatched pair unchanged", "'-mod=readonly\"", "'-mod=readonly\""},
		{"double layer strips one layer", `"'-mod=readonly'"`, "'-mod=readonly'"},
		{"one-character token unchanged", "'", "'"},
		{"empty token unchanged", "", ""},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := UnquoteGoflagsToken(tt.token); got != tt.want {
				t.Errorf("UnquoteGoflagsToken(%q) = %q, want %q", tt.token, got, tt.want)
			}
		})
	}
}
```

